///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            if (fnAKCKwdSearchCodeType(($c.util.getComponent('AKCKwd')))) {
                await scwin.fnInit();
            }
        }
    }
};

/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnInit = async function () {
    $c.util.getComponent("dma_fnSearch1Req").set("orderMode", "0");
    $c.util.getComponent("dma_fnSearch1Req").set("orderStat", "D");
    $c.util.getComponent("dma_fnSearch1Req").set("pageIndex", "1");
    await scwin.fnSearchCorpName('S');
};

/**
 * @method
 * @name fnOrder
 * @description fn Order 처리
 * @param {*} mode mode
 * @param {*} stat stat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnOrder = async function (mode, stat) {
    $c.util.getComponent("dma_fnSearch1Req").set("orderMode", mode);
    $c.util.getComponent("dma_fnSearch1Req").set("orderStat", stat);
    $c.util.getComponent("dma_fnSearch1Req").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnDateSearch
 * @description fn Date Search 처리
 * @param {*} val val
 * @param {Number} idx idx
 * @param {*} isSearch isSearch
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDateSearch = async function (val, idx, isSearch) {
    $("#searchForm").find("a[id=tabDay]").each(function(index) {
            if ($(this).hasClass("active")) {
                $(this).removeClass("active");
            }
            if (index === idx) {
                $(this).addClass("active");
            }
    });
    if ($("#otherTabDay").find("span").hasClass("active")) {
        $("#otherTabDay").find("span").removeClass("active");
    }
    if (idx === -1) {
        if (!$("#otherTabDay").find("span").hasClass("active")) {
            $("#otherTabDay").find("span").addClass("active");
        }
    }
    if (idx === 0) {
        $c.util.getComponent("dma_fnSearch1Req").set("todayFlag", "Y");
    } else {
        $c.util.getComponent("dma_fnSearch1Req").set("todayFlag", "N");
    }
    $("#searchForm").find('input[id=cal_selDate]').val(val);
    if (isSearch) {
        await scwin.fnInit();
    }
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    $c.util.getComponent('AKCKwd').setValue(comAbbrv);
    $c.util.getComponent("dma_fnSearch1Req").set("repIsuSrtCd", "A" + repIsuSrtCd);
    $c.util.getComponent("dma_fnSearch1Req").set("searchCodeType", "char");
};

/**
 * @method
