/**
 * @method
 * @name fnRssOpen
 * @description fn Rss Open 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnRssOpen = async function () {
    let marketType = ($c.util.getComponent("dma_fnSearch1Req").get("marketType") || '');
    if (marketType === "") {
        marketType = "0";
    }
    const obj = new scwin.fnObjDetectBrowser();
    const ver = obj.version;
    let openPopupFlag = true;
    if (obj.isIE) {
        if (ver === "6") {
            await $c.win.alert('IE6버전에서는 RSS 피드읽기가 지원되지 않습니다.\n정상적인 서비스을 위해서 RSS리더를 사용해 주세요.');
            openPopupFlag = false;
        } else {
            if (ver === "7") {
                await $c.win.alert('IE7버전에서 RSS 피드읽기 사용이 아닌 경우 XML로 표시됩니다.\n정상적인 서비스를 위해 아래와 같이 설정 후 사용해 주세요.\n[도구] - [인터넷옵션] - [내용] - [피드 및 웹 조각] : 설정 - [피드 읽기용 보기 사용] 항목 : 체크');
            }
        }
    }
    if (openPopupFlag) {
        const valRepIsuSrtCd = ($c.util.getComponent("dma_fnSearch1Req").get("repIsuSrtCd") || '');
        const valSearchCorpName = $c.util.getComponent('AKCKwd').getValue();
        const valCurrentPageSize = ($c.util.getComponent("dma_fnSearch1Req").get("currentPageSize") || '');
        const wUrl = "/disclosure/rsstodaydistribute.do?method=searchRssTodayDistribute&repIsuSrtCd=" + valRepIsuSrtCd + "&mktTpCd=" + marketType + "&searchCorpName=" + valSearchCorpName + "&currentPageSize=" + valCurrentPageSize;
        // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
        $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(wUrl), { id: "오늘의공시RSS", width: "700", height: "700", scrollbars: true, resizable: true, type: "pageFramePopup" }, {});
    }
};

/**
 * @method
 * @name fnObjDetectBrowser
 * @description fn Obj Detect Browser 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnObjDetectBrowser = function () {
    let strUA, s, i;
    this.isIE = false;
    this.isNS = false;
    this.version = null;
    strUA = navigator.userAgent;
    s = "MSIE";
    if ((i = strUA.indexOf(s)) >= 0) {
        this.isIE = true;
        this.version = parseFloat(strUA.substr(i + s.length));
        return;
    }
    s = "Netscape6/";
    if ((i = strUA.indexOf(s)) >= 0) {
        this.isNS = true;
        this.version = parseFloat(strUA.substr(i + s.length));
        return;
    }
    s = "Gecko";
    if ((i = strUA.indexOf(s)) >= 0) {
        this.isNS = true;
        this.version = 6.1;
        return;
    }
};

/**
 * @method
 * @name fnRssCopyUrl
 * @description fn Rss Copy Url 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnRssCopyUrl = async function () {
    let marketType = ($c.util.getComponent("dma_fnSearch1Req").get("marketType") || '');
    const valRepIsuSrtCd = ($c.util.getComponent("dma_fnSearch1Req").get("repIsuSrtCd") || '');
    const valSearchCorpName = $c.util.getComponent('AKCKwd').getValue();
    const valCurrentPageSize = ($c.util.getComponent("dma_fnSearch1Req").get("currentPageSize") || '');
    if (marketType === "") {
        marketType = "0";
    }
    const wUrl = "http://null:null/disclosure/rsstodaydistribute.do?method=searchRssTodayDistribute&repIsuSrtCd=" + valRepIsuSrtCd + "&mktTpCd=" + marketType + "&searchCorpName=" + valSearchCorpName + "&currentPageSize=" + valCurrentPageSize;
    const copyUrl = $c.util.getComponent("ipt_copyUrl");
    $c.util.getComponent("dma_fnSearch1Req").set("copyUrl", wUrl);
    copyUrl.type = 'text';
    copyUrl.setReadOnly(true);
    copyUrl.select();
    copyUrl.setSelectionRange(0, 99999);
    document.execCommand("copy");
    copyUrl.type = 'hidden';
    await $c.win.alert("RSS주소가 복사되었습니다. RSS Reader 프로그램에 입력하시기 바랍니다.");
};

